package robert.purdey.caddytracker.security.encryption;

import java.math.BigInteger;
import java.security.spec.RSAPublicKeySpec;
import java.util.Base64;

public class ServerRsaPublicKeyInfo
{
    public static final BigInteger MODULUS          = new BigInteger("");
    public static final BigInteger PUBLIC_EXP       = new BigInteger("65537");
    public static final RSAPublicKeySpec RSA_KEY    = new RSAPublicKeySpec(MODULUS, PUBLIC_EXP);

    public static RSAPublicKeySpec GetRsaPublicKeySpec()
    {
        byte[] modulusBytes  = Base64.getDecoder().decode("");
        byte[] exponentBytes = Base64.getDecoder().decode("AQAB");

        BigInteger keyMod = new BigInteger(1, modulusBytes);
        BigInteger pubExp = new BigInteger(1, exponentBytes);

        return new RSAPublicKeySpec(keyMod, pubExp);
    }
}

